// 共享候选：原Office、人物控制、生命和辖区全史之后才核旧撤职的新增完整来源。
#include "political_dismissal_world.hpp"
#include "world_bundle.hpp"
namespace hanmo::resident {namespace {
Status available(const WorldBundle& w){return w.catalog->political_dismissal_sources&&w.political_dismissal_sources&&w.politics_enabled()&&w.catalog->organization&&w.catalog->organization->enabled&&w.family_life_enabled()&&w.catalog->common&&w.catalog->family?common_success():common_failure("PoliticalDismissalSourceProfileRequired");}
bool actual_result(const CommitResult& r,const StableId& source,const StableId& office){const auto* e=r.details?std::get_if<PoliticsEffects>(&r.details->data):nullptr;return r.ok&&r.kind=="political_dismiss"&&e&&e->appointment_id.empty()&&e->fact_ids==std::vector<StableId>{source,office}&&e->receipt_ids==e->fact_ids;}
Status player(const WorldBundle& w,const StableId& actor){auto v=command_common_guard(w,actor,"political_dismiss");if(!v.ok)return v;return actor==w.common.state().metadata.player_actor_id?common_success():common_failure("PoliticalDismissalPlayerOnly");}
}
PoliticalDismissalWorldAccess::PoliticalDismissalWorldAccess(const WorldBundle& w):world_(w),military_(w.political_takeover_enabled()?std::optional<MilitaryAccess>{w.services.military_access()}:std::nullopt),occupations_(w.political_takeover_enabled()?std::optional<PoliticalSuccessionOccupationContext>{PoliticalSuccessionOccupationContext{w.political_takeover,*w.catalog->political_takeover,w.military,*w.catalog->military,*military_}}:std::nullopt),territory_{w.common,w.politics,*w.catalog->politics,occupations_?&*occupations_:nullptr},rules_{w.common,*w.catalog->common,w.politics,*w.catalog->politics,w.organization,*w.catalog->organization,w.local_economy,w.services,*w.catalog->political_dismissal_sources,*w.political_dismissal_sources,w.family_death_read(),[this](const PoliticalDismissalSourcePolicy& p,Integer tick,const StableId& fact){return validate_political_dismissal_seats(territory_,p,tick,fact);},[&w](Integer tick,const StableId& fact){return read_political_dismissal_player_before_fact(w.common,w.family,w.family_legacy_enabled()?&w.family_legacy:nullptr,tick,fact);},actual_result}{}
Outcome<std::unique_ptr<PoliticalDismissalWorldAccess>> PoliticalDismissalWorldAccess::create(const WorldBundle& w){auto v=available(w);if(!v.ok)return {false,{},v.error};return {true,std::unique_ptr<PoliticalDismissalWorldAccess>{new PoliticalDismissalWorldAccess(w)},{}};}
Status validate_political_dismissal_world(const WorldBundle& w){auto v=validate_political_dismissal_source_layout(w.common,w.catalog->identity.module_versions,w.political_dismissal_sources?&*w.political_dismissal_sources:nullptr);if(!v.ok)return v;if(bool(w.catalog->political_dismissal_sources)!=w.political_dismissal_sources.has_value())return common_failure("PoliticalDismissalSourceProfileMismatch");if(!w.catalog->political_dismissal_sources)return common_success();auto read=PoliticalDismissalWorldAccess::create(w);return read.ok?validate_political_dismissal_sources_complete(read.value->context()):Status{false,{},read.error};}
Status preview_political_dismissal_world(const WorldBundle& w,const StableId& actor,const PoliticalDismissCommand& c){auto valid=player(w,actor);if(!valid.ok)return valid;auto read=PoliticalDismissalWorldAccess::create(w);if(!read.ok)return {false,{},read.error};auto quote=preview_political_dismissal_source(read.value->context(),actor,c);return quote.ok?common_success():Status{false,{},quote.error};}
Outcome<PoliticsEffects> commit_political_dismissal_world(WorldBundle& w,const StableId& actor,const PoliticalDismissCommand& c){auto valid=player(w,actor);if(!valid.ok)return {false,{},valid.error};auto read=PoliticalDismissalWorldAccess::create(w);if(!read.ok)return {false,{},read.error};auto quote=preview_political_dismissal_source(read.value->context(),actor,c);if(!quote.ok)return {false,{},quote.error};return apply_political_dismissal_with_source(w.common,w.politics,w.organization,*w.political_dismissal_sources,read.value->context(),actor,c,quote.value);}
Status bind_political_dismissal_result_world(WorldBundle& w,const StableId& source,const StableId& actor,Integer request,const CommitResult& r){if(!w.catalog->political_dismissal_sources||!w.political_dismissal_sources||source.empty()||r.kind!="political_dismiss")return common_failure("PoliticalDismissalNewSourceRequired");return bind_political_dismissal_result(w.common,*w.political_dismissal_sources,source,actor,request,r,actual_result);}
}
